import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { excursions } from '../../Data/excursions';
import './CartPage.css';

const CartPage = () => {
  // MOCK корзины
  const [cartItems, setCartItems] = useState(
    excursions.slice(0, 2).map(item => ({
      ...item,
      guests: 1
    }))
  );

  // ➕ увеличить количество
  const increaseGuests = (id) => {
    setCartItems(prev =>
      prev.map(item =>
        item.id === id
          ? { ...item, guests: item.guests + 1 }
          : item
      )
    );
  };

  // ➖ уменьшить количество (не меньше 1)
  const decreaseGuests = (id) => {
    setCartItems(prev =>
      prev.map(item =>
        item.id === id && item.guests > 1
          ? { ...item, guests: item.guests - 1 }
          : item
      )
    );
  };

  // ❌ удалить из корзины
  const removeFromCart = (id) => {
    setCartItems(prev => prev.filter(item => item.id !== id));
  };

  // 💰 итоговая сумма
  const totalPrice = cartItems.reduce(
    (sum, item) => sum + item.price * item.guests,
    0
  );

  return (
    <div className="cart-page">
      <div className="cart-container">
        <h1 className="cart-title">Корзина</h1>

        {cartItems.length === 0 ? (
          <div className="cart-empty">
            <img
              src="/assets/icons/cart.svg"
              alt="Пустая корзина"
              className="empty-icon"
            />
            <h2>Корзина пуста</h2>
            <p>Добавьте экскурсии из каталога</p>
            <Link to="/catalog" className="browse-button">
              Перейти в каталог
            </Link>
          </div>
        ) : (
          <>
            <div className="cart-list">
              {cartItems.map(item => (
                <div key={item.id} className="cart-item">
                  <img
                    src={item.image}
                    alt={item.title}
                    className="cart-item__image"
                  />

                  <div className="cart-item__info">
                    <h3>{item.title}</h3>
                    <p>{item.country}, {item.city}</p>

                    <div className="cart-item__controls">
                      <button
                        className="qty-btn"
                        onClick={() => decreaseGuests(item.id)}
                        disabled={item.guests === 1}
                      >
                        −
                      </button>

                      <span className="qty-value">
                        {item.guests}
                      </span>

                      <button
                        className="qty-btn"
                        onClick={() => increaseGuests(item.id)}
                      >
                        +
                      </button>
                    </div>

                    <button
                      className="cart-item__remove"
                      onClick={() => removeFromCart(item.id)}
                    >
                      Удалить
                    </button>
                  </div>

                  <div className="cart-item__total">
                    {(item.price * item.guests).toLocaleString()} ₽
                  </div>
                </div>
              ))}
            </div>

            <div className="cart-summary">
              <div className="cart-summary__total">
                Итого: <strong>{totalPrice.toLocaleString()} ₽</strong>
              </div>

              <button className="cart-checkout-btn">
                Оформить заказ
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
};

export default CartPage;
